(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y * 0.018 + t * 0.3) * 12 + Math.cos(x * 0.012 - t * 0.2) * 8;
  const w1y = Math.cos(x * 0.015 - t * 0.25) * 12 + Math.sin(y * 0.01 + t * 0.35) * 8;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sy * 0.025 - t * 0.4) * 6 + Math.cos(sx * 0.02 + t * 0.3) * 4;
  const w2y = Math.cos(sx * 0.022 + t * 0.35) * 6 + Math.sin(sy * 0.018 - t * 0.45) * 4;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [240+Math.sin(t*0.45+0.5)*180, 120+Math.cos(t*0.65+0.5)*100, 0.05, 3.0],
    [100+Math.cos(t*0.55+3)*120, 50+Math.sin(t*0.75+2)*80, 0.11, 1.3],
    [380+Math.sin(t*0.38+1.5)*100, 200+Math.cos(t*0.58+2.5)*60, 0.085, 2.1]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  for (let k = 0; k < src.length; k++) {
    const [sX, sY, f, sp] = src[k];
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS2 += Math.sin(d*f*1.8 - t*sp*1.3 + 0.7) * 0.5;
    iS2 += Math.sin(d*f*1.3 + t*sp*0.9 + 2.8) * 0.5;
  }
  const n = src.length;
  const act = aS/n + aS2/n, inh = iS/n + iS2/n;
  const bg = (Math.sin(wx*0.04+wy*0.025+t*0.8) + Math.sin(wx*0.03-wy*0.04+t*1.1) + Math.sin(wx*0.08-wy*0.06+t*1.5)*0.5 + Math.sin(wx*0.06+wy*0.08-t*1.8)*0.5) / 3 + Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((wx-cx)**2 + (wy-cy)**2), ang = Math.atan2(wy-cx, wx-cx);
