  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const reaction2 = Math.tanh((reaction*1.5 - act*0.3 + inh*0.2)*1.8);
  const cell = Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15) + Math.sin((wx+wy)*0.1+t)*0.5 + Math.sin(wx*0.255-wy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const edge = Math.abs(reaction2 - reaction);
  const noise = (Math.sin(wx*0.45+wy*0.3+t*3)*Math.sin(wx*0.35-wy*0.4-t*2.5))*0.08;
  const blend = reaction2*0.55 + reaction*0.2 + cell*0.2 + noise;
  const v = blend*0.5+0.5;
  const pal = [[5,12,58],[12,50,95],[18,100,128],[30,155,148],[80,185,110],[165,198,65],[225,188,48],[230,140,52],[205,82,58],[165,48,72],[110,28,68],[55,18,60],[5,12,58]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82 + Math.sin(reaction2*Math.PI)*0.18;
